// The evidence registry: every number behind a recommendation, what kind of evidence it is, where it comes from,
// how far to trust it, and whether that claim is checked by a test. It exists so that a sceptical agronomist,
// Earth scientist or judge can trace any value to its source - and see plainly which parts are measured, which are
// published science, which are rules of thumb and which are our own assumptions.
//
// `kind` - what the value is:
//   observed    measured by an instrument (satellite gravimetry, radar elevation)
//   modeled     data produced by a model from observations (reanalysis weather, SoilGrids soil maps)
//   literature  a parameter or method from peer-reviewed science or an institutional standard (FAO, IPCC)
//   heuristic   a rule of thumb or a design choice of ours, informed by agronomic guidance but not measured
//   farmer      entered by the farmer (history, priorities, lab test, water budget)
//   projection  a climate projection (CMIP6) - a scenario, not a forecast
//   assumption  a placeholder value we chose where no fitting evidence exists (prices, costs); replace locally
// `checked` - how the claim "this value comes from that source" is backed:
//   tested  a unit test compares the code with a transcription of the source (see decision.test.ts)
//   cited   the source is named; the value was not re-checked row by row against it
//   none    a design choice or assumption, nothing to check against

export type EvidenceKind = 'observed' | 'modeled' | 'literature' | 'heuristic' | 'farmer' | 'projection' | 'assumption'
export type Checked = 'tested' | 'cited' | 'none'

export type Source = { id: string; short: string; full: string; url?: string; type: 'institution' | 'peer-reviewed' | 'dataset' | 'regulation' | 'extension' }

